@Bulkhead(name = "payments")
public PaymentResult chargeCustomer(Order order) {
    return paymentClient.charge(order);
}

private PaymentResult paymentFallback(Order order, Throwable t) {
    return PaymentResult.failFast("payment provider unavailable, please retry");
}

@CircuitBreaker(name = "recommendations", fallbackMethod = "recFallback")
